//! Serves the web UI: the build of `ui/` embedded at compile time, or a
//! directory on disk during development.

use std::path::{Component, Path, PathBuf};
use std::sync::Arc;

use axum::extract::State;
use axum::http::{header, HeaderValue, Method, StatusCode, Uri};
use axum::response::{IntoResponse, Response};

use crate::api::ApiError;
use crate::state::AppState;

// `ASSETS: &[(&str, &[u8])]`, generated by build.rs from `ui/dist`.
include!(concat!(env!("OUT_DIR"), "/ui_assets.rs"));

const CONTENT_SECURITY_POLICY: &str = "default-src 'self'; style-src 'self' 'unsafe-inline'; \
     img-src 'self' data:; connect-src 'self' ws: wss:; frame-ancestors 'none'; base-uri 'self'";

fn content_type(path: &str) -> &'static str {
    match path.rsplit('.').next().unwrap_or("") {
        "html" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" | "map" => "application/json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "ico" => "image/x-icon",
        "woff2" => "font/woff2",
        "txt" => "text/plain; charset=utf-8",
        _ => "application/octet-stream",
    }
}

fn embedded(path: &str) -> Option<Vec<u8>> {
    ASSETS.iter().find(|(name, _)| *name == path).map(|(_, bytes)| bytes.to_vec())
}

/// Reads `path` below `dir`, refusing anything that would leave it.
async fn from_disk(dir: &Path, path: &str) -> Option<Vec<u8>> {
    let relative = PathBuf::from(path);
    if !relative.components().all(|part| matches!(part, Component::Normal(_))) {
        return None;
    }
    tokio::fs::read(dir.join(relative)).await.ok()
}

async fn load(state: &AppState, path: &str) -> Option<Vec<u8>> {
    match &state.config.ui_dir {
        Some(dir) => from_disk(dir, path).await,
        None => embedded(path),
    }
}

/// Fallback for everything that is not an API or client route.
pub async fn serve(State(state): State<Arc<AppState>>, method: Method, uri: Uri) -> Response {
    let path = uri.path();
    if path.starts_with("/api/") || path.starts_with("/client/") || path == "/api" {
        return ApiError::new(StatusCode::NOT_FOUND, "not_found", "no such route").into_response();
    }
    if method != Method::GET && method != Method::HEAD {
        return StatusCode::METHOD_NOT_ALLOWED.into_response();
    }

    let requested = path.trim_start_matches('/');
    let (name, body) = match load(&state, requested).await {
        Some(body) if !requested.is_empty() => (requested, body),
        // Client-side routes: every unknown path is the application itself.
        _ => match load(&state, "index.html").await {
            Some(body) => ("index.html", body),
            None => return StatusCode::NOT_FOUND.into_response(),
        },
    };

    // Vite puts content hashes in the names under assets/.
    let cache = if name.starts_with("assets/") {
        "public, max-age=31536000, immutable"
    } else {
        "no-cache"
    };
    let mut response = (StatusCode::OK, body).into_response();
    let headers = response.headers_mut();
    headers.insert(header::CONTENT_TYPE, HeaderValue::from_static(content_type(name)));
    headers.insert(header::CACHE_CONTROL, HeaderValue::from_static(cache));
    headers.insert(header::X_CONTENT_TYPE_OPTIONS, HeaderValue::from_static("nosniff"));
    headers.insert(header::X_FRAME_OPTIONS, HeaderValue::from_static("DENY"));
    headers.insert(header::REFERRER_POLICY, HeaderValue::from_static("no-referrer"));
    headers.insert(
        header::CONTENT_SECURITY_POLICY,
        HeaderValue::from_static(CONTENT_SECURITY_POLICY),
    );
    response
}
